import {M78_FUGITIVE_METHOD,M78_REVIEWED_POLICY} from './m78-policy'
import {m78CanonicalJson,m78Finding,m78Fail,deriveM78ProcessFindings} from './m78-validation'
import type {M78Proof,M78Version,M78Family,M78Dependencies,M78SourceVersion,M78SourceFamily,M78Finding,M78GasContribution,M78Totals,M78Rollup,M78Reconciliation} from './m78-contract'
type Hash=(v:unknown)=>string
type Decimal={n:bigint;s:number}
const pow=(s:number)=>10n**BigInt(s)
function decimal(v:string):Decimal{if(typeof v!=='string'||!/^(0|[1-9]\d{0,39})(\.\d{1,30})?$/.test(v))m78Fail('Nonnegative bounded exact decimal required.');const [a,b='']=v.split('.');return {n:BigInt(a!+b),s:b.length}}
function exact(d:Decimal):string{const neg=d.n<0n,n=neg?-d.n:d.n,s=n.toString().padStart(d.s+1,'0'),out=d.s?s.slice(0,-d.s)+'.'+s.slice(-d.s):s;return (neg?'-':'')+(out.includes('.')?out.replace(/0+$/,'').replace(/\.$/,''):out)}
function plus(a:Decimal,b:Decimal):Decimal{const s=Math.max(a.s,b.s);return {n:a.n*pow(s-a.s)+b.n*pow(s-b.s),s}}
export function m78Sum(values:string[]):string{return exact(values.map(decimal).reduce(plus,{n:0n,s:0}))}
export function m78Multiply(a:string,b:string):string{const x=decimal(a),y=decimal(b);return exact({n:x.n*y.n,s:x.s+y.s})}
export function m78Display(value:string):string{const d=decimal(value);let n=d.n;if(d.s<4)n*=pow(4-d.s);else if(d.s>4){const p=pow(d.s-4),q=n/p,r=n%p;n=q+(2n*r>p||2n*r===p&&q%2n===1n?1n:0n)}return (n/10000n).toString()+'.'+(n%10000n).toString().padStart(4,'0')}
const pin=(v:{id:string;versionSha256:string})=>({id:v.id,sha256:v.versionSha256})
const decision=(r:{id:string;decisionSha256:string}|null|undefined)=>r?{id:r.id,sha256:r.decisionSha256}:null
export function m78MethodPayload(family:M78SourceFamily,v:M78SourceVersion):unknown{const c=v.calculation;if(!c)return null;if(family==='fugitive'){const f=c as any;const d=M78_FUGITIVE_METHOD,g=d.gases.find(g=>g.gas===f.gas);if(f.method!==d.id||f.gwp_basis!==d.gwpBasis||f.factor_source_sha256!==d.sourceSha256||f.guidance_sha256!==d.guidanceSha256||!g||f.gwp!==g.gwp||f.factor_locator!==g.locator)m78Fail('Fugitive method/policy descriptor parity failed.');return d}return (c as any).method}
function physical(p:M78Proof,family:M78SourceFamily,v:M78SourceVersion):string|null{const sourceId=v.activity.binding.sourceId;if(family==='natural_gas')return p.stationary.reconciliation.rows.find(r=>r.sourceId===sourceId&&r.worksheetIds.includes((v as any).worksheetId))?.equipmentId??null;return (v.activity as any).equipment?.assetId??(v.activity as any).vehicle?.assetId??(v.activity as any).assetId??null}
export function buildM78Dependencies(p:M78Proof,family:M78Family,hash:Hash):M78Dependencies{const inventory=family==='inventory',body={coveragePin:pin(p.coverageVersion),coverageReviewPin:decision(p.coverageVersion.review),processVersionPin:inventory&&p.process?pin(p.process.version):null,processReviewPin:inventory?decision(p.process?.review):null,sourcePins:p.sourceVersions.map(({family,version:v})=>({family,worksheetId:(v as any).worksheetId??(v as any).streamId,sourceId:v.activity.binding.sourceId,physicalId:physical(p,family,v),version:pin(v),decision:decision(v.review)})).sort((a,b)=>a.worksheetId<b.worksheetId?-1:1),discoveryPins:(['fleet','stationary','fugitive'] as const).map(family=>{const d=p[family];return {family,version:d.version?pin(d.version):null,decision:decision(d.review),dependencySha256:d.reconciliation.dependencySha256,reconciliationSha256:d.reconciliation.contentSha256}}),policySha256:inventory?p.policy?.policySha256??null:null,rulesVersion:'m78-gross-scope1-v1' as const};return {...body,dependencySha256:hash(body)}}
const scope1=new Set(['stationary_combustion','mobile_combustion','fugitive','process'])
const boundary=new Set(['unsupported_consolidation','unsupported_geography','unsupported_temporal_allocation','unsupported_boundary_relationship','control_evidence_missing','boundary_unreconciled','boundary_basis_missing','boundary_assertion_unverified'])
export function mapM78CorporateFindings(p:M78Proof,hash:Hash):M78Finding[]{const c=p.coverageVersion,s=c.snapshot,rows=new Map([...s.entities,...s.facilities,...s.relationships,...s.boundaryDecisions,...s.coverageItems,...s.requirements].map(r=>[r.id,r])),deps=buildM78Dependencies(p,'inventory',hash),processAccepted=p.process?.review?.decision==='accepted_bounded_process_screen'&&p.process.version.activity.binding.coverageVersionId===c.id&&p.process.version.activity.binding.coverageVersionSha256===c.versionSha256&&m78CanonicalJson(p.process.version.dependencies)===m78CanonicalJson(buildM78Dependencies(p,'process_screen',hash))&&!deriveM78ScreenFindings(p.process.version.activity as any,p,hash).some(f=>f.classification==='functional_blocker');
 return c.findings.map(f=>{const row=f.recordId?rows.get(f.recordId):undefined,domain=(row as any)?.domain;let classification:M78Finding['classification']='functional_blocker',resolution:M78Finding['resolution']=null;if(boundary.has(f.code))classification='functional_blocker';else if(f.code==='synthetic_evidence_not_sufficient'||f.code==='methods_not_released')classification='release_blocker';else if(['requirements_not_determined','requirement_unknown','requirement_conflicting'].includes(f.code)||domain&&!scope1.has(domain))classification='corporate_gap';else if(scope1.has(domain)){const sourceId=(row as any).sourceId,matched=sourceId?p.sourceVersions.filter(x=>x.version.activity.binding.sourceId===sourceId):[],candidate=matched.length===1&&matched[0]!.version.review?.decision==='accepted_bounded_internal'&&matched[0]!.version.calculation!==null&&matched[0]!.version.activity.binding.coverageVersionId===c.id&&matched[0]!.version.activity.binding.coverageVersionSha256===c.versionSha256;const group=(row as any).entityId===null&&sourceId===null;const d=domain==='mobile_combustion'?p.fleet:domain==='stationary_combustion'?p.stationary:p.fugitive;const discovery=group&&domain!=='process'&&d.reconciliation.status==='reconciled_bounded_synthetic'&&d.review?.decision==='accepted_bounded_reconciliation'&&d.version&&(d.version as any).activity.coverageVersionId===c.id;const supported=domain==='process'?group&&processAccepted:sourceId?candidate:discovery;if(supported&&['activity_unknown','evidence_incomplete','method_unsupported','screening_assertion_unverified'].includes(f.code)){classification='resolved_bounded';resolution={ruleId:domain==='process'?'accepted_process_screen':sourceId?'current_reviewed_source':'current_reviewed_discovery',pins:domain==='process'?[deps.processVersionPin!,deps.processReviewPin!]:sourceId?[pin(matched[0]!.version),decision(matched[0]!.version.review)!]:[pin(d.version!),decision(d.review)!]}}}
