export function m78ValidateProcessCorrection(prior:M78ProcessActivity|null,next:M78ProcessActivity){for(const a of prior?.assessments.filter(a=>a.discoveredSourceId!==null)??[]){const n=next.assessments.find(n=>n.discoveredSourceId===a.discoveredSourceId);if(!n||n.disposition!=='indicated'||n.category!==a.category)m78Fail('Previously discovered process sources cannot be removed, renamed or reassigned.')}for(const g of prior?.gasCoverage??[]){const nextGroup=next.gasCoverage.find(n=>n.gasGroup===g.gasGroup);if(g.discoveredSourceIds.some(id=>!nextGroup?.discoveredSourceIds.includes(id)))m78Fail('Previously indicated gas sources cannot be removed or reclassified.')}for(const l of prior?.locations??[]){const n=next.locations.find(n=>n.rowId===l.rowId);if(!n||n.entityId!==l.entityId||n.facilityId!==l.facilityId||n.operationId!==l.operationId)m78Fail('Previously discovered location/operation identities must remain retained.')}}
