export function deriveM78ProcessFindings(a:M78ProcessActivity,c:M71Version):M78Finding[]{const out:M78Finding[]=[],add=(s:string,m:string,id:string|null=null)=>out.push(m78Finding(s,m,id,'process_screen')),d=a.declaration;if(!d||d.completeness!=='declared_complete'||!d.allControlledOperationsIncluded||!a.manualConfirmation)add('process_discovery_incomplete','Complete discovery and evidence confirmation are required.');if(d&&(m78CanonicalJson([...d.coveredEntityIds].sort())!==m78CanonicalJson(c.snapshot.entities.map(e=>e.id).sort())||m78CanonicalJson([...d.coveredFacilityIds].sort())!==m78CanonicalJson(c.snapshot.facilities.map(f=>f.id).sort())))add('process_scope_incomplete','Discovery must cover every retained entity and location.');for(const f of c.snapshot.facilities)if(!a.locations.some(l=>l.facilityId===f.id&&l.entityId===f.entityId))add('process_location_missing','Retained location has no process inspection.',f.id);
