create function neuvetra.m78_lock(target_company uuid,writing boolean)returns boolean language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$begin if not neuvetra.m71_lock(target_company,writing)then return false;end if;if writing then perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.scope1_heads where company_id=target_company order by id for update;else perform id from neuvetra.companies where id=target_company for share;end if;return true;end $$;
create function neuvetra.m78_pin(v jsonb,review boolean default false)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when v is null or v='null'::jsonb then 'null'::jsonb else jsonb_build_object('id',v->'id','sha256',v->case when review then 'decisionSha256'else 'versionSha256'end)end$$;
create function neuvetra.m78_finding(code text,message text,record_id text default null,family text default 'm78',classification text default 'functional_blocker',resolution jsonb default null)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_object('code',code,'origin',jsonb_build_object('family',family,'recordId',record_id,'originalCode',code),'classification',classification,'message',message,'resolution',resolution)$$;
create function neuvetra.m78_limitations()returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '["synthetic_only","scope1_incomplete","corporate_inventory_incomplete","factor_and_method_not_released","requirements_not_determined","no_external_assurance"]'::jsonb$$;
create function neuvetra.m78_physical(p jsonb,family text,v jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case family when 'fugitive'then v#>'{activity,assetId}' when 'mobile_diesel'then v#>'{activity,vehicle,assetId}'when 'stationary_diesel'then v#>'{activity,equipment,assetId}'else coalesce((select r->'equipmentId'from jsonb_array_elements(p#>'{stationary,reconciliation,rows}')r where r->'sourceId'=v#>'{activity,binding,sourceId}'limit 1),'null'::jsonb)end$$;
create function neuvetra.m78_dependencies(p jsonb,family text)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with body as(select jsonb_build_object('coveragePin',neuvetra.m78_pin(p->'coverageVersion'),'coverageReviewPin',neuvetra.m78_pin(p#>'{coverageVersion,review}',true),'processVersionPin',case when family='inventory'then neuvetra.m78_pin(p#>'{process,version}')else 'null'::jsonb end,'processReviewPin',case when family='inventory'then neuvetra.m78_pin(p#>'{process,review}',true)else 'null'::jsonb end,'sourcePins',coalesce((select jsonb_agg(jsonb_build_object('family',x->'family','worksheetId',coalesce(x#>'{version,worksheetId}',x#>'{version,streamId}'),'sourceId',x#>'{version,activity,binding,sourceId}','physicalId',neuvetra.m78_physical(p,x->>'family',x->'version'),'version',neuvetra.m78_pin(x->'version'),'decision',neuvetra.m78_pin(x#>'{version,review}',true))order by coalesce(x#>>'{version,worksheetId}',x#>>'{version,streamId}')collate "C")from jsonb_array_elements(p->'sourceVersions')x),'[]'::jsonb),'discoveryPins',(select jsonb_agg(jsonb_build_object('family',k,'version',neuvetra.m78_pin(p#>array[k,'version']),'decision',neuvetra.m78_pin(p#>array[k,'review'],true),'dependencySha256',p#>array[k,'reconciliation','dependencySha256'],'reconciliationSha256',p#>array[k,'reconciliation','contentSha256'])order by n)from unnest(array['fleet','stationary','fugitive'])with ordinality q(k,n)),'policySha256',case when family='inventory'then coalesce(p#>'{policy,policySha256}','null'::jsonb)else 'null'::jsonb end,'rulesVersion','m78-gross-scope1-v1')b)select b||jsonb_build_object('dependencySha256',neuvetra.m67_hash(b))from body$$;
create function neuvetra.m78_contributors(p jsonb,prior jsonb,actor uuid,family text)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_agg(to_jsonb(k)order by k collate "C")from(select distinct k from(select x#>>'{}'k from jsonb_array_elements(coalesce(prior->'contributorIds','[]'::jsonb))x union all select x#>>'{}'from jsonb_array_elements(p#>'{coverageVersion,contributorIds}')x union all select x#>>'{}'from jsonb_array_elements(p->'sourceVersions')v,jsonb_array_elements(v#>'{version,contributorIds}')x union all select x#>>'{}'from unnest(array['fleet','stationary','fugitive'])d,jsonb_array_elements(coalesce(p#>array[d,'version','contributorIds'],'[]'::jsonb))x union all select x#>>'{}'from jsonb_array_elements(case when family='inventory'then coalesce(p#>'{process,version,contributorIds}','[]'::jsonb)else '[]'::jsonb end)x union all select actor::text)q)r$$;

