d:=a->'declaration';if d<>'null'::jsonb then perform neuvetra.m71_keys(d,'completeness,coveredEntityIds,coveredFacilityIds,allControlledOperationsIncluded,discoveryBasis');if coalesce(d->>'completeness','')not in('unknown','partial','declared_complete')or jsonb_typeof(d->'allControlledOperationsIncluded')is distinct from 'boolean'then raise exception 'discovery declaration required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(d->'coveredEntityIds',150,'uuid');perform neuvetra.m78_sorted_strings(d->'coveredFacilityIds',150,'uuid');perform neuvetra.m76_diesel_text(d->'discoveryBasis',2000);if length(d->>'discoveryBasis')<20 then raise exception 'discovery basis required'using errcode='22023';end if;end if;
foreach k in array array['locations','assessments','gasCoverage','evidenceStatements']loop if jsonb_typeof(a->k)is distinct from 'array'or jsonb_array_length(a->k)>(case k when 'locations'then 25 when 'gasCoverage'then 7 else 100 end)then raise exception 'process capacity'using errcode='22023';end if;end loop;
for x in select value from jsonb_array_elements(a->'locations')loop perform neuvetra.m71_keys(x,'rowId,entityId,facilityId,operationId,businessActivities,equipmentAndMaterials,controlExplanation,evidenceReferences');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'rowId'),1,'uuid');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'entityId'),1,'uuid');if(x->'facilityId'='null'::jsonb)=(x->'operationId'='null'::jsonb)then raise exception 'facility or operation required'using errcode='22023';end if;if x->'facilityId'<>'null'::jsonb then perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'facilityId'),1,'uuid');else perform neuvetra.m77_id(x->'operationId');end if;perform neuvetra.m76_diesel_text(x->'businessActivities',2000);perform neuvetra.m76_diesel_text(x->'equipmentAndMaterials',2000);perform neuvetra.m76_diesel_text(x->'controlExplanation',2000);perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');end loop;
for x in select value from jsonb_array_elements(a->'assessments')loop perform neuvetra.m71_keys(x,'rowId,category,discoveredSourceId,locationRowIds,disposition,reason,evidenceReferences');perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'rowId'),1,'uuid');if coalesce(x->>'category','')not in('mineral_products','chemical_production','metal_production','oil_and_gas','waste_treatment','agricultural_biological','other_direct_process')or coalesce(x->>'disposition','')not in('unknown','indicated','not_applicable_proposed')or(x->>'disposition'='indicated')=(x->'discoveredSourceId'='null'::jsonb)then raise exception 'process assessment required'using errcode='22023';end if;if x->'discoveredSourceId'<>'null'::jsonb then perform neuvetra.m77_id(x->'discoveredSourceId');end if;perform neuvetra.m78_sorted_strings(x->'locationRowIds',25,'uuid');perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');if x->'reason'<>'null'::jsonb then perform neuvetra.m76_diesel_text(x->'reason',2000);end if;end loop;
for x in select value from jsonb_array_elements(a->'gasCoverage')loop perform neuvetra.m71_keys(x,'gasGroup,state,sourceIds,discoveredSourceIds,locationRowIds,reason,evidenceReferences');if coalesce(x->>'gasGroup','')not in('CO2','CH4','N2O','HFCs','PFCs','SF6','NF3')or coalesce(x->>'state','')not in('unknown','indicated','not_applicable_proposed','covered_by_sources')then raise exception 'gas applicability required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(x->'sourceIds',150,'uuid');perform neuvetra.m78_sorted_strings(x->'discoveredSourceIds',100,'id');perform neuvetra.m78_sorted_strings(x->'locationRowIds',25,'uuid');perform neuvetra.m78_sorted_strings(x->'evidenceReferences',100,'id');if x->'reason'<>'null'::jsonb then perform neuvetra.m76_diesel_text(x->'reason',2000);end if;if x->>'state'='covered_by_sources'and jsonb_array_length(x->'sourceIds')=0 or x->>'state'='indicated'and jsonb_array_length(x->'discoveredSourceIds')=0 or x->>'state'<>'indicated'and jsonb_array_length(x->'discoveredSourceIds')<>0 or x->>'state'='not_applicable_proposed'and jsonb_array_length(x->'sourceIds')<>0 then raise exception 'gas state source conflict'using errcode='22023';end if;end loop;
for x in select value from jsonb_array_elements(a->'evidenceStatements')loop perform neuvetra.m71_keys(x,'reference,issuer,description,issuedOn,purpose,entityId,facilityId');perform neuvetra.m77_id(x->'reference');perform neuvetra.m76_diesel_text(x->'issuer',120);perform neuvetra.m76_diesel_text(x->'description',2000);if length(x->>'description')<20 or coalesce(x->>'purpose','')not in('business_activity','process_inspection','offsite_discovery')or to_char((x->>'issuedOn')::date,'YYYY-MM-DD')is distinct from x->>'issuedOn'then raise exception 'dated statement required'using errcode='22023';end if;perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'entityId'),1,'uuid');if x->'facilityId'<>'null'::jsonb then perform neuvetra.m78_sorted_strings(jsonb_build_array(x->'facilityId'),1,'uuid');end if;end loop;
foreach k in array array['locations','assessments','gasCoverage','evidenceStatements']loop perform neuvetra.m78_sorted_strings((select coalesce(jsonb_agg(x->case k when 'gasCoverage'then 'gasGroup'when 'evidenceStatements'then 'reference'else 'rowId'end order by n),'[]')from jsonb_array_elements(a->k)with ordinality q(x,n)),100,'text');end loop;if jsonb_array_length(a->'gasCoverage')<>7 then raise exception 'all seven gas groups required'using errcode='22023';end if;
perform neuvetra.m78_sorted_strings((select coalesce(jsonb_agg(x->'discoveredSourceId'order by x->>'discoveredSourceId'collate "C"),'[]')from jsonb_array_elements(a->'assessments')x where x->'discoveredSourceId'<>'null'::jsonb),100,'id');if octet_length(neuvetra.m67_canonical(a))>200000 then raise exception 'activity capacity exceeded'using errcode='22023';end if;
end $$;

create function neuvetra.m78_process_findings(a jsonb,c jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare out jsonb:='[]';d jsonb:=a->'declaration';x jsonb;l jsonb;e jsonb;g jsonb;id text;k text;group_rows jsonb;locations jsonb;begin
if d='null'::jsonb or d->>'completeness'<>'declared_complete'or d->'allControlledOperationsIncluded'<>'true'::jsonb or a->'manualConfirmation'<>'true'::jsonb then out:=out||jsonb_build_array(neuvetra.m78_finding('process_discovery_incomplete','Complete discovery and evidence confirmation are required.',null,'process_screen'));end if;
select coalesce(jsonb_agg(x->'rowId'order by x->>'rowId'collate "C"),'[]')into locations from jsonb_array_elements(a->'locations')x;
if d<>'null'::jsonb and(d->'coveredEntityIds'is distinct from(select jsonb_agg(x->'id'order by x->>'id'collate "C")from jsonb_array_elements(c#>'{snapshot,entities}')x)or d->'coveredFacilityIds'is distinct from coalesce((select jsonb_agg(x->'id'order by x->>'id'collate "C")from jsonb_array_elements(c#>'{snapshot,facilities}')x),'[]'))then out:=out||jsonb_build_array(neuvetra.m78_finding('process_scope_incomplete','Discovery must cover every retained entity and location.',null,'process_screen'));end if;
for x in select value from jsonb_array_elements(c#>'{snapshot,facilities}')loop if not exists(select 1 from jsonb_array_elements(a->'locations')l where l->'facilityId'=x->'id'and l->'entityId'=x->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_missing','Retained location has no process inspection.',x->>'id','process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(a->'evidenceStatements')loop if not exists(select 1 from jsonb_array_elements(c#>'{snapshot,entities}')e where e->'id'=x->'entityId')or x->'facilityId'<>'null'::jsonb and not exists(select 1 from jsonb_array_elements(c#>'{snapshot,facilities}')f where f->'id'=x->'facilityId'and f->'entityId'=x->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_evidence_location_unknown','Statement location does not resolve.',x->>'reference','process_screen'));end if;end loop;
for l in select value from jsonb_array_elements(a->'locations')loop
 if not exists(select 1 from jsonb_array_elements(c#>'{snapshot,entities}')e where e->'id'=l->'entityId')or l->'facilityId'<>'null'::jsonb and not exists(select 1 from jsonb_array_elements(c#>'{snapshot,facilities}')f where f->'id'=l->'facilityId'and f->'entityId'=l->'entityId')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_unknown','Inspection location does not resolve.',l->>'rowId','process_screen'));end if;
 if jsonb_array_length(l->'evidenceReferences')=0 or exists(select 1 from jsonb_array_elements_text(l->'evidenceReferences')r where not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->>'reference'=r and e->'entityId'=l->'entityId'and e->'facilityId'=l->'facilityId'))or not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where l->'evidenceReferences'? (e->>'reference')and e->>'purpose'='business_activity')or not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where l->'evidenceReferences'?(e->>'reference')and e->>'purpose'=case when l->'facilityId'='null'::jsonb then 'offsite_discovery'else 'process_inspection'end)then out:=out||jsonb_build_array(neuvetra.m78_finding('process_location_evidence_missing','Inspection requires retained activity and location-matched discovery evidence.',l->>'rowId','process_screen'));end if;
end loop;
for x in select value from jsonb_array_elements(c#>'{snapshot,entities}')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->'entityId'=x->'id'and e->'facilityId'='null'::jsonb and e->>'purpose'='offsite_discovery')then out:=out||jsonb_build_array(neuvetra.m78_finding('process_offsite_evidence_missing','Every entity needs explicit controlled non-facility discovery evidence.',x->>'id','process_screen'));end if;end loop;
foreach k in array array['mineral_products','chemical_production','metal_production','oil_and_gas','waste_treatment','agricultural_biological','other_direct_process']loop select coalesce(jsonb_agg(x),'[]')into group_rows from jsonb_array_elements(a->'assessments')x where x->>'category'=k and x->'discoveredSourceId'='null'::jsonb;if jsonb_array_length(group_rows)<>1 or group_rows#>'{0,locationRowIds}'is distinct from locations then out:=out||jsonb_build_array(neuvetra.m78_finding('process_category_scope_incomplete','Every category requires one full-discovery assessment.',k,'process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(a->'assessments')loop
 if x->>'disposition'<>'not_applicable_proposed'then out:=out||jsonb_build_array(neuvetra.m78_finding(case when x->>'disposition'='indicated'then 'process_method_unsupported'else 'process_applicability_unknown'end,'Process applicability or indicated method remains unresolved.',coalesce(nullif(x->>'discoveredSourceId',''),x->>'rowId'),'process_screen'));end if;
 if x->'reason'='null'::jsonb or jsonb_array_length(x->'evidenceReferences')=0 or exists(select 1 from jsonb_array_elements_text(x->'evidenceReferences')r where not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->>'reference'=r))or exists(select 1 from jsonb_array_elements_text(x->'locationRowIds')r where not exists(select 1 from jsonb_array_elements(a->'locations')l where l->>'rowId'=r))then out:=out||jsonb_build_array(neuvetra.m78_finding('process_assessment_evidence_missing','Assessment rationale and references must resolve.',x->>'rowId','process_screen'));end if;
 for l in select value from jsonb_array_elements(a->'locations')l where x->'locationRowIds'?(l->>'rowId')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where x->'evidenceReferences'?(e->>'reference')and e->'entityId'=l->'entityId'and e->'facilityId'=l->'facilityId'and e->>'purpose'=case when l->'facilityId'='null'::jsonb then 'offsite_discovery'else 'process_inspection'end)then out:=out||jsonb_build_array(neuvetra.m78_finding('process_assessment_location_evidence_missing','Assessment lacks inspected-location support.',x->>'rowId','process_screen'));end if;end loop;
end loop;
for g in select value from jsonb_array_elements(a->'gasCoverage')loop
 if g->>'state'in('unknown','indicated')then out:=out||jsonb_build_array(neuvetra.m78_finding(case when g->>'state'='unknown'then 'gas_applicability_unknown'else 'indicated_gas_source_unsupported'end,'Gas applicability or indicated source is unresolved.',g->>'gasGroup','process_screen'));end if;
 if g->'reason'='null'::jsonb or g->'locationRowIds'is distinct from locations or exists(select 1 from jsonb_array_elements_text(g->'evidenceReferences')r where not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where e->>'reference'=r))or exists(select 1 from jsonb_array_elements_text(g->'sourceIds')r where not exists(select 1 from jsonb_array_elements(c#>'{snapshot,sources}')s where s->>'id'=r and s->>'domain'in('stationary_combustion','mobile_combustion','fugitive','process')))then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_scope_evidence_missing','Every gas group needs exact source and full-discovery evidence.',g->>'gasGroup','process_screen'));end if;
 for x in select value from jsonb_array_elements(c#>'{snapshot,entities}')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where g->'evidenceReferences'?(e->>'reference')and e->'entityId'=x->'id'and e->'facilityId'='null'::jsonb and e->>'purpose'='offsite_discovery')then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_offsite_evidence_missing','Gas scope requires explicit non-facility discovery evidence for every entity.',g->>'gasGroup','process_screen'));end if;end loop;
 for l in select value from jsonb_array_elements(a->'locations')loop if not exists(select 1 from jsonb_array_elements(a->'evidenceStatements')e where g->'evidenceReferences'?(e->>'reference')and e->'entityId'=l->'entityId'and e->'facilityId'=l->'facilityId'and e->>'purpose'=case when l->'facilityId'='null'::jsonb then 'offsite_discovery'else 'process_inspection'end)then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_location_evidence_missing','Gas applicability lacks retained inspected-location support.',g->>'gasGroup','process_screen'));end if;end loop;
end loop;
for x in select value from jsonb_array_elements(c#>'{snapshot,sources}')where value->>'domain'='process'loop out:=out||jsonb_build_array(neuvetra.m78_finding('corporate_process_source_unsupported','Corporate process source requires a supported method.',x->>'id','process_screen'));end loop;return out;
end $$;

create function neuvetra.m78_gas_sources(p jsonb,gas_group text)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select coalesce(jsonb_agg(x order by n),'[]')from jsonb_array_elements(p->'sourceVersions')with ordinality q(x,n)where case when x->>'family'='fugitive'then gas_group='HFCs'and(x#>>'{version,activity,gas}'like 'HFC-%'or x#>>'{version,activity,gas}'='R-410A')or gas_group=x#>>'{version,activity,gas}'else gas_group in('CO2','CH4','N2O')end$$;
create function neuvetra.m78_screen_findings(a jsonb,p jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare out jsonb:=neuvetra.m78_process_findings(a,p->'coverageVersion');f jsonb;g jsonb;x jsonb;actual jsonb;d text;begin
for f in select value from jsonb_array_elements(p#>'{coverageVersion,findings}')where value->>'code'in('unsupported_consolidation','unsupported_geography','unsupported_temporal_allocation','unsupported_boundary_relationship','control_evidence_missing','boundary_unreconciled','boundary_basis_missing','boundary_assertion_unverified')loop out:=out||jsonb_build_array(neuvetra.m78_finding('corporate_scope1_boundary_blocked',f->>'message',f->>'recordId','process_screen'));end loop;
if p#>>'{coverageVersion,review,decision}'is distinct from 'accepted_bounded_internal'then out:=out||jsonb_build_array(neuvetra.m78_finding('corporate_review_required','Current corporate boundary requires exact review.',null,'process_screen'));end if;
for g in select value from jsonb_array_elements(a->'gasCoverage')loop actual:=neuvetra.m78_gas_sources(p,g->>'gasGroup');if jsonb_array_length(actual)>0 and g->>'state'<>'covered_by_sources'or g->>'state'='covered_by_sources'and g->'sourceIds'is distinct from coalesce((select jsonb_agg(x#>'{version,activity,binding,sourceId}'order by x#>>'{version,activity,binding,sourceId}'collate "C")from jsonb_array_elements(actual)x),'[]')then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_source_coverage_conflict','Gas applicability must name every exact source in the discovered population.',g->>'gasGroup','process_screen'));end if;if g->>'state'<>'covered_by_sources'then continue;end if;
foreach d in array array['fleet','stationary','fugitive']loop if p#>>array[d,'reconciliation','status']is distinct from 'reconciled_bounded_synthetic'or p#>>array[d,'review','decision']is distinct from 'accepted_bounded_reconciliation'then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_physical_population_unreconciled','Positive gas coverage requires independently reconciled complete physical populations.',g->>'gasGroup','process_screen'));end if;end loop;
for x in select value from jsonb_array_elements(actual)loop if x#>'{version,calculation}'='null'::jsonb or x#>>'{version,review,decision}'is distinct from 'accepted_bounded_internal'or x#>'{version,activity,binding,coverageVersionId}'is distinct from p#>'{coverageVersion,id}'or x#>'{version,activity,binding,coverageVersionSha256}'is distinct from p#>'{coverageVersion,versionSha256}'then out:=out||jsonb_build_array(neuvetra.m78_finding('gas_source_incomplete','Positive gas coverage requires current exact supported source review.',x#>>'{version,activity,binding,sourceId}','process_screen'));end if;end loop;
end loop;return out;end $$;
create function neuvetra.m78_corporate_findings(p jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare out jsonb:='[]';c jsonb:=p->'coverageVersion';s jsonb:=c->'snapshot';deps jsonb:=neuvetra.m78_dependencies(p,'inventory');f jsonb;row jsonb;domain text;source_id text;matched jsonb;candidate boolean;group_row boolean;discovery boolean;supported boolean;d jsonb;classification text;resolution jsonb;process_accepted boolean;begin
process_accepted:=p#>>'{process,review,decision}'='accepted_bounded_process_screen'and p#>'{process,version,activity,binding,coverageVersionId}'=c->'id'and p#>'{process,version,activity,binding,coverageVersionSha256}'=c->'versionSha256'and p#>'{process,version,dependencies}'=neuvetra.m78_dependencies(p,'process_screen')and not exists(select 1 from jsonb_array_elements(neuvetra.m78_screen_findings(p#>'{process,version,activity}',p))x where x->>'classification'='functional_blocker');
for f in select value from jsonb_array_elements(c->'findings')loop row:=null;select x into row from jsonb_array_elements((s->'entities')||(s->'facilities')||(s->'relationships')||(s->'boundaryDecisions')||(s->'coverageItems')||(s->'requirements'))x where x->'id'=f->'recordId'limit 1;domain:=row->>'domain';classification:='functional_blocker';resolution:=null;
if f->>'code'in('unsupported_consolidation','unsupported_geography','unsupported_temporal_allocation','unsupported_boundary_relationship','control_evidence_missing','boundary_unreconciled','boundary_basis_missing','boundary_assertion_unverified')then classification:='functional_blocker';elsif f->>'code'in('synthetic_evidence_not_sufficient','methods_not_released')then classification:='release_blocker';elsif f->>'code'in('requirements_not_determined','requirement_unknown','requirement_conflicting')or domain is not null and domain not in('stationary_combustion','mobile_combustion','fugitive','process')then classification:='corporate_gap';elsif domain in('stationary_combustion','mobile_combustion','fugitive','process')then
source_id:=row->>'sourceId';select coalesce(jsonb_agg(x),'[]')into matched from jsonb_array_elements(p->'sourceVersions')x where x#>>'{version,activity,binding,sourceId}'=source_id;candidate:=jsonb_array_length(matched)=1 and matched#>>'{0,version,review,decision}'='accepted_bounded_internal'and matched#>'{0,version,calculation}'<>'null'::jsonb and matched#>'{0,version,activity,binding,coverageVersionId}'=c->'id'and matched#>'{0,version,activity,binding,coverageVersionSha256}'=c->'versionSha256';group_row:=row->'entityId'='null'::jsonb and row->'sourceId'='null'::jsonb;d:=p->case domain when 'mobile_combustion'then 'fleet'when 'stationary_combustion'then 'stationary'else 'fugitive'end;discovery:=group_row and domain<>'process'and d#>>'{reconciliation,status}'='reconciled_bounded_synthetic'and d#>>'{review,decision}'='accepted_bounded_reconciliation'and d->'version'<>'null'::jsonb and d#>'{version,activity,coverageVersionId}'=c->'id';supported:=case when domain='process'then group_row and process_accepted when source_id is not null then candidate else discovery end;
if supported and f->>'code'in('activity_unknown','evidence_incomplete','method_unsupported','screening_assertion_unverified')then classification:='resolved_bounded';resolution:=jsonb_build_object('ruleId',case when domain='process'then 'accepted_process_screen'when source_id is not null then 'current_reviewed_source'else 'current_reviewed_discovery'end,'pins',case when domain='process'then jsonb_build_array(deps->'processVersionPin',deps->'processReviewPin')when source_id is not null then jsonb_build_array(neuvetra.m78_pin(matched#>'{0,version}'),neuvetra.m78_pin(matched#>'{0,version,review}',true))else jsonb_build_array(neuvetra.m78_pin(d->'version'),neuvetra.m78_pin(d->'review',true))end);end if;end if;
out:=out||jsonb_build_array(neuvetra.m78_finding(f->>'code',f->>'message',f->>'recordId','corporate',classification,resolution));end loop;return out;end $$;

create function neuvetra.m78_gas_lines(rows jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select coalesce(jsonb_agg(jsonb_build_object('gas',gas,'gasKind',kind,'massKgExact',neuvetra.m76_diesel_exact(mass),'kgCo2eExact',neuvetra.m76_diesel_exact(co2e))order by gas collate "C"),'[]')from(select x->>'gas'gas,min(x->>'gasKind')kind,sum((x->>'massKgExact')::numeric)mass,sum((x->>'co2eKgExact')::numeric)co2e from jsonb_array_elements(rows)x group by x->>'gas')q$$;
create function neuvetra.m78_rollup_row(id text,label text,rows jsonb)returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_object('id',id,'label',label,'kgCo2eExact',neuvetra.m76_diesel_exact(n),'kgCo2eDisplay',neuvetra.m76_diesel_display(n),'gasLines',neuvetra.m78_gas_lines(rows))from(select coalesce(sum((x->>'co2eKgExact')::numeric),0)n from jsonb_array_elements(rows)x)q$$;
create function neuvetra.m78_rollup(p jsonb,rows jsonb)returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$
#variable_conflict use_column
declare sources jsonb:='[]';facilities jsonb:='[]';entities jsonb:='[]';x jsonb;filtered jsonb;n numeric;displayed numeric;begin
for x in select value from jsonb_array_elements(p#>'{coverageVersion,snapshot,sources}')loop select coalesce(jsonb_agg(r),'[]')into filtered from jsonb_array_elements(rows)r where r->'sourceId'=x->'id';if jsonb_array_length(filtered)>0 then sources:=sources||jsonb_build_array(neuvetra.m78_rollup_row(x->>'id',x->>'name',filtered));end if;end loop;
