export async function m78BaselineDigests(c:WorkspaceConnection,tables?:string[]){const names=tables??(await c.query<{name:string}>("select table_schema||'.'||table_name name from information_schema.tables where table_schema='neuvetra' and table_type='BASE TABLE' and table_name<>'schema_migrations' order by table_name")).rows.map(r=>r.name);const out:{table:string;count:string;sha256:string}[]=[];for(const table of names){if(!/^neuvetra\.[a-z0-9_]+$/.test(table))throw Error('Unsafe table.');const r=(await c.query<{count:string;content:string}>(`select count(*)::text count,coalesce(string_agg(neuvetra.m67_canonical(to_jsonb(t)),E'\n' order by neuvetra.m67_canonical(to_jsonb(t)) collate "C"),'')content from ${table} t`)).rows[0]!;out.push({table,count:r.count,sha256:new Bun.CryptoHasher('sha256').update(r.content).digest('hex')})}return out}
